end

function ElementBreakInfoPanel:Awake()
    xTry(function()
       -- self.txtInfoLocked = self.Node_BreakInfo_Locked:Find('Txt_Desc'):GetComponent(typeof(Text))
        self.switchTextLeft = self.TitleLeft.gameObject:GetComponent(typeof(UISwitchText))
        self.switchTextRight = self.TitleRight.gameObject:GetComponent(typeof(UISwitchText))
        KTool.SetActive(self.Node_BreakInfo_Break.gameObject, false)
        KTool.SetActive(self.Node_BreakInfo_Locked.gameObject, false)
        self.cgElementBreakInfo = self.controller.gameObject:GetComponent(typeof(CanvasGroup))
        
        self:SetRootRightShowStatus()
    end)
end

function ElementBreakInfoPanel:Start()
end

