function ElementBreakInfoPanel:ShowPanel(isShow)
    isShow = checkBool(isShow)
    if not IsNull(self.cgElementBreakInfo) then
        self.cgElementBreakInfo.alpha = isShow and 1 or 0
    end
    KTool.SetActive(self.RightTitleNode.gameObject, isShow)
    KTool.SetActive(self.LeftTitleNode.gameObject, isShow)
end


---SetWeaknessData
---@param weaknessVo WeakVo 弱点信息Vo
function ElementBreakInfoPanel:SetWeaknessData(weaknessVo)
    local weakData = weaknessVo
    self:GetDescWeak(weakData.weakShow)
    self:GetDescSleep(weakData.sleepShow)
    self:GetDescRage(weakData.rageShow)
end

function ElementBreakInfoPanel:GetDescWeak(strWeak)
    if IsNull(strWeak) or strWeak == "" then return end
    local results = string.split2(strWeak, ";")
    self.listDescWeak = results
end

function ElementBreakInfoPanel:GetDescSleep(strSleep)
    if IsNull(strSleep) or strSleep == "" then return end
    local results = string.split2(strSleep, "_")
    for i = 1, #results do
        if results[i] == "round" then
            results[i] = "%d"
        end
    end
    self.descSleep = table.concat(results)
end

function ElementBreakInfoPanel:GetDescRage(strRage)
    if IsNull(strRage) or strRage == "" then return end
    local results = string.split2(strRage, ";")
    self.listDescRage = results
end

