---设置 解体等待回合数
---@param sleepLength number 解体等待时长
function ElementBreakInfoPanel:SetBreakWaitingLength(sleepLength)
    self.numSleepLength = sleepLength
    --self.txtInfoLocked.text = localize("_num_回合后进入狂暴状态（可解体）", {_num_ = checkInt(self.numSleepLength)})
end

