function ElementBreakInfoPanel:SetConditionNodes(listData, rootFather, status)
    if IsNull(listData) or #listData <= 0 then return end
    local count = #listData
    local listNode = self:GetGOBreakInfo(count, rootFather)
    for i = 1, #listNode do
        local node = listNode[i]
        node:SetTextDesc(listData[i], status)
    end
end

------------ SetData ------------

------------ InfoNode ------------

---GetGOBreakInfo
---生成阶梯信息预设
---@param numEffects number 效果条目数
function ElementBreakInfoPanel:GetGOBreakInfo(numEffects, rootFather)
    local listNode = {}
    for i = 1, numEffects do
        local node = GameObject.Instantiate(self.Node_BreakInfo_Break.gameObject, rootFather)
        if node then
            KTool.SetActive(node, true)
            local nodeLB = GetLuaBehaviour(node, PATH_BREAK_INFO)
            if nodeLB then
                nodeLB:Init()
                local tableNode = nodeLB.Env
                self:InsertElement2ListBreakInfo(tableNode.controller)
                table.insert(listNode, tableNode)
            end
        end
    end
    return listNode
end

function ElementBreakInfoPanel:CleanListDescNodes()
    if self.listBreakInfo and #self.listBreakInfo > 0 then
        for i = #self.listBreakInfo, 1, -1 do
            KTool.SafeDelete(self.listBreakInfo[i].gameObject)
        end
        self.listBreakInfo = nil
    end
end

function ElementBreakInfoPanel:InsertElement2ListBreakInfo(tableNode)
    if isNull(self.listBreakInfo) then
        self.listBreakInfo = {}
    end
    table.insert(self.listBreakInfo, tableNode)
end

