function ElementBreakInfoPanel:GetListData(key)
    local data = {
        [DescType.Rage] = self.listDescRage,
        [DescType.Weak] = self.listDescWeak,
    }
    return data[key]
end

function ElementBreakInfoPanel:GetTitleInfo(type, Part)
    local _leftInfo = {
        [PanelShowState.Sleep] = { title = DescType.Rage, status = 1, type = DescType.Rage },
        [PanelShowState.Running] = { title = DescType.Rage, status = 2, type = DescType.Rage },
        [PanelShowState.Weakness] = { title = DescType.Weak, status = 3, type = DescType.Weak },
    }
    local _rightInfo = {
        [PanelShowState.Sleep] = { title = DescType.Weak, status = 2, type = DescType.Weak },
        [PanelShowState.Running] = { title = DescType.Weak, status = 3, type = DescType.Weak },
        [PanelShowState.Weakness] = { title = DescType.Rage, status = 2, type = DescType.Rage },
    }
    return Part == DescPart.Left and _leftInfo[type] or _rightInfo[type]
end

function ElementBreakInfoPanel:SetRootLeftInfo(type)
    local infoData = self:GetTitleInfo(type, DescPart.Left)
    self.TitleLeft.text = infoData.title
    self.switchTextLeft.Status = infoData.status
    self.LeftTitleNode.Status = infoData.status
    self.TitlePTCLeft.Status = infoData.status - 1
    self:SetConditionNodes(self:GetListData(infoData.type), self.LeftLayout, infoData.status)
end

function ElementBreakInfoPanel:SetRootRightInfo(type)
    local infoData = self:GetTitleInfo(type, DescPart.Right)
    self.TitleRight.text = infoData.title
    self:SetConditionNodes(self:GetListData(infoData.type), self.RightLayout,  infoData.status)
end

function ElementBreakInfoPanel:RefreshInfo(type)
    self:CleanListDescNodes()
    self:SetRootLeftInfo(type)
    self:SetRootRightInfo(type)
end

function ElementBreakInfoPanel:SetRootRightShowStatus()
    self.switchTextRight.Status = 1
    self.RightTitleNode.Status = 1
    KTool.SetActive(self.TitlePTCRight.gameObject, false)
end

